// static
bool DownloadControllerStubDispatch::Accept(
    DownloadController* impl,
    mojo::Message* message) {
  switch (message->header()->name) {
    case internal::kDownloadController_BindClient_Name: {

      DCHECK(message->is_serialized());
      internal::DownloadController_BindClient_Params_Data* params =
          reinterpret_cast<internal::DownloadController_BindClient_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      ::mojo::PendingRemote<DownloadControllerClient> p_client{};
      DownloadController_BindClient_ParamsDataView input_data_view(params, message);
      
      if (success) {
        p_client =
            input_data_view.TakeClient<decltype(p_client)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DownloadController::Name_, 3, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->BindClient(
std::move(p_client));
      return true;
    }
    case internal::kDownloadController_OnDownloadCreated_Name: {

      DCHECK(message->is_serialized());
      internal::DownloadController_OnDownloadCreated_Params_Data* params =
          reinterpret_cast<internal::DownloadController_OnDownloadCreated_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      DownloadItemPtr p_download{};
      DownloadController_OnDownloadCreated_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadDownload(&p_download))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DownloadController::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnDownloadCreated(
std::move(p_download));
      return true;
    }
    case internal::kDownloadController_OnDownloadUpdated_Name: {

      DCHECK(message->is_serialized());
      internal::DownloadController_OnDownloadUpdated_Params_Data* params =
          reinterpret_cast<internal::DownloadController_OnDownloadUpdated_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      DownloadItemPtr p_download{};
      DownloadController_OnDownloadUpdated_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadDownload(&p_download))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DownloadController::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnDownloadUpdated(
std::move(p_download));
      return true;
    }
    case internal::kDownloadController_OnDownloadDestroyed_Name: {

      DCHECK(message->is_serialized());
      internal::DownloadController_OnDownloadDestroyed_Params_Data* params =
          reinterpret_cast<internal::DownloadController_OnDownloadDestroyed_Params_Data*>(
              message->mutable_payload());
      
      bool success = true;
      DownloadItemPtr p_download{};
      DownloadController_OnDownloadDestroyed_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadDownload(&p_download))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            DownloadController::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->OnDownloadDestroyed(
std::move(p_download));
      return true;
    }
  }
  return false;
}

