// static
bool StructTraits<::crosapi::mojom::DownloadItem::DataView, ::crosapi::mojom::DownloadItemPtr>::Read(
    ::crosapi::mojom::DownloadItem::DataView input,
    ::crosapi::mojom::DownloadItemPtr* output) {
  bool success = true;
  ::crosapi::mojom::DownloadItemPtr result(::crosapi::mojom::DownloadItem::New());
  
      if (success && !input.ReadState(&result->state))
        success = false;
      if (success && !input.ReadTargetFilePath(&result->target_file_path))
        success = false;
      if (success)
        result->is_from_incognito_profile = input.is_from_incognito_profile();
      if (success && !input.ReadGuid(&result->guid))
        success = false;
      if (success && !input.ReadFullPath(&result->full_path))
        success = false;
      if (success)
        result->has_is_paused = input.has_is_paused();
      if (success)
        result->is_paused = input.is_paused();
      if (success)
        result->has_open_when_complete = input.has_open_when_complete();
      if (success)
        result->open_when_complete = input.open_when_complete();
      if (success)
        result->has_received_bytes = input.has_received_bytes();
      if (success)
        result->received_bytes = input.received_bytes();
      if (success)
        result->has_total_bytes = input.has_total_bytes();
      if (success)
        result->total_bytes = input.total_bytes();
      if (success && !input.ReadStartTime(&result->start_time))
        success = false;
      if (success)
        result->has_is_dangerous = input.has_is_dangerous();
      if (success)
        result->is_dangerous = input.is_dangerous();
      if (success)
        result->has_is_insecure = input.has_is_insecure();
      if (success)
        result->is_insecure = input.is_insecure();
      if (success && !input.ReadDangerType(&result->danger_type))
        success = false;
      if (success && !input.ReadInsecureDownloadStatus(&result->insecure_download_status))
        success = false;
  *output = std::move(result);
  return success;
}

