DownloadControllerClientAsyncWaiter::DownloadControllerClientAsyncWaiter(
    DownloadControllerClient* proxy) : proxy_(proxy) {}

DownloadControllerClientAsyncWaiter::~DownloadControllerClientAsyncWaiter() = default;

void DownloadControllerClientAsyncWaiter::GetAllDownloads(
    std::vector<DownloadItemPtr>* out_downloads) {
  base::RunLoop loop;
  proxy_->GetAllDownloads(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<DownloadItemPtr>* out_downloads
,
             std::vector<DownloadItemPtr> downloads) {*out_downloads = std::move(downloads);
            loop->Quit();
          },
          &loop,
          out_downloads));
  loop.Run();
}

std::vector<DownloadItemPtr> DownloadControllerClientAsyncWaiter::GetAllDownloads(
    ) {
  std::vector<DownloadItemPtr> async_wait_result;
  GetAllDownloads(&async_wait_result);
  return async_wait_result;
}




